 "content": "def transform(grid):
    """Draw color-3 straight segments between aligned marker cells."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != 3}
    out = [row[:] for row in grid]
    # Join every pair of markers sharing a row or column, preserving endpoints.
    for r, c in markers:
        for rr, cc in markers:
            if rr == r and cc != c:
                for x in range(min(c, cc) + 1, max(c, cc)):
                    if out[r][x] == bg:
                        out[r][x] = 3
            elif cc == c and rr != r:
                for y in range(min(r, rr) + 1, max(r, rr)):
                    if out[y][c] == bg:
                        out[y][c] = 3
    return out
